const overview = $('Fetch Executive Summary').item.json;
const insights = $('Fetch Active Directives').all().map(i => i.json);

let htmlReport = `
<h2>SalesPulse Weekly Executive Business Intelligence Briefing</h2>
<p><strong>Generated:</strong> ${new Date().toUTCString()}</p>
<hr/>
<h3>1. Financial Performance Snapshot</h3>
<ul>
  <li><strong>Total Gross Revenue:</strong> $${Number(overview.kpis.total_revenue).toLocaleString()}</li>
  <li><strong>Total Net Profit:</strong> $${Number(overview.kpis.total_profit).toLocaleString()}</li>
  <li><strong>Blended Profit Margin:</strong> ${overview.kpis.profit_margin_pct.toFixed(2)}%</li>
  <li><strong>Total Orders:</strong> ${overview.kpis.total_orders.toLocaleString()}</li>
  <li><strong>Average Order Value:</strong> $${overview.kpis.average_order_value.toFixed(2)}</li>
</ul>

<h3>2. Top Prioritized Strategic Directives</h3>
<ol>
`;

insights.slice(0, 3).forEach(ins => {
  htmlReport += `
    <li>
      <strong>[${ins.priority}] ${ins.title}</strong><br/>
      <em>Metric:</em> ${ins.metric}<br/>
      <em>Directive:</em> ${ins.action}
    </li>
  `;
});

htmlReport += `</ol><hr/><p><em>SalesPulse Enterprise Intelligence Platform</em></p>`;

return { htmlReport, total_revenue: overview.kpis.total_revenue };
